-- Connected operating records. All access goes through pageant-core authorization.
alter table public.pageant_activities add constraint pageant_activity_project_pair unique(id,project_id);
create table public.pageant_course_plans(
 activity_id uuid primary key,project_id uuid not null references public.pageant_projects(id),objectives text not null default '',audience text not null default '',requirements text not null default '',instructor text not null default '',syllabus jsonb not null default '[]',materials jsonb not null default '[]',status text not null default 'draft' check(status in('draft','published')),version integer not null default 1,updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),foreign key(activity_id,project_id)references public.pageant_activities(id,project_id));
create table public.pageant_lessons(
 id uuid primary key default gen_random_uuid(),project_id uuid not null references public.pageant_projects(id),activity_id uuid not null,title text not null,starts_at timestamptz,ends_at timestamptz,venue text not null default '',instructor text not null default '',preparation text not null default '',materials jsonb not null default '[]',status text not null default 'draft' check(status in('draft','scheduled','completed','cancelled')),version integer not null default 1,created_by uuid references auth.users(id),updated_at timestamptz not null default now(),unique(id,project_id),foreign key(activity_id,project_id)references public.pageant_activities(id,project_id),check(ends_at is null or starts_at is null or ends_at>starts_at));
create table public.pageant_lesson_attendance(
 lesson_id uuid not null references public.pageant_lessons(id),user_id uuid not null references auth.users(id),status text not null check(status in('present','absent','excused')),note text not null default '',updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),primary key(lesson_id,user_id));
create table public.pageant_homework(
 id uuid primary key default gen_random_uuid(),project_id uuid not null references public.pageant_projects(id),activity_id uuid not null,title text not null,instructions text not null default '',due_at timestamptz,material_url text not null default '',status text not null default 'draft' check(status in('draft','open','closed')),version integer not null default 1,created_by uuid references auth.users(id),updated_at timestamptz not null default now(),foreign key(activity_id,project_id)references public.pageant_activities(id,project_id));
create table public.pageant_submissions(
 id uuid primary key default gen_random_uuid(),homework_id uuid not null references public.pageant_homework(id),user_id uuid not null references auth.users(id),body text not null default '',link text not null default '',status text not null default 'submitted' check(status in('submitted','reviewed')),feedback text not null default '',reviewed_by uuid references auth.users(id),version integer not null default 1,submitted_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(homework_id,user_id));
create table public.pageant_guest_invites(
 id uuid primary key default gen_random_uuid(),project_id uuid not null references public.pageant_projects(id),activity_id uuid,title text not null default '',display_name text not null,email text not null default '',kind text not null default 'guest' check(kind in('guest','vip','judge','sponsor','media','host','performer')),message text not null default '',status text not null default 'draft' check(status in('draft','invited','accepted','declined','contact')),token_hash text unique,expires_at timestamptz,revoked_at timestamptz,replied_at timestamptz,reply_note text not null default '',party_size integer not null default 1,max_party_size integer not null default 1 check(max_party_size between 1 and 10),version integer not null default 1,created_by uuid references auth.users(id),updated_at timestamptz not null default now(),foreign key(activity_id,project_id)references public.pageant_activities(id,project_id));
create table public.pageant_sponsor_packages(
 id uuid primary key default gen_random_uuid(),project_id uuid not null references public.pageant_projects(id),title text not null,summary text not null default '',kind text not null default 'cash' check(kind in('cash','inkind','media','venue')),amount integer check(amount is null or amount>=0),benefits jsonb not null default '[]',activity_id uuid,status text not null default 'draft' check(status in('draft','published','withdrawn')),version integer not null default 1,created_by uuid references auth.users(id),updated_at timestamptz not null default now(),unique(id,project_id),foreign key(activity_id,project_id)references public.pageant_activities(id,project_id));
create table public.pageant_sponsor_leads(
 id uuid primary key default gen_random_uuid(),project_id uuid not null references public.pageant_projects(id),package_id uuid,user_id uuid references auth.users(id),company text not null,contact_name text not null default '',email text not null default '',phone text not null default '',brief text not null default '',status text not null default 'new' check(status in('new','contacted','proposed','confirmed','declined','completed')),staff_note text not null default '',member_message text not null default '',confirmation text not null default '',consent_at timestamptz,request_key uuid,version integer not null default 1,created_by uuid references auth.users(id),updated_at timestamptz not null default now(),unique(id,project_id),unique(user_id,request_key),foreign key(package_id,project_id)references public.pageant_sponsor_packages(id,project_id));
create table public.pageant_sponsor_deliverables(
 id uuid primary key default gen_random_uuid(),project_id uuid not null references public.pageant_projects(id),lead_id uuid not null,title text not null,due_at timestamptz,status text not null default 'pending' check(status in('pending','doing','done')),proof_url text not null default '',proof_text text not null default '',article_id uuid references public.pageant_articles(id),asset_id uuid references public.pageant_assets(id),version integer not null default 1,created_by uuid references auth.users(id),updated_at timestamptz not null default now(),foreign key(lead_id,project_id)references public.pageant_sponsor_leads(id,project_id));
create table public.pageant_campaigns(
 id uuid primary key default gen_random_uuid(),project_id uuid not null references public.pageant_projects(id),activity_id uuid,title text not null,channel text not null default 'website' check(channel in('website','facebook','line','instagram','video','press','invitation')),caption text not null default '',due_at timestamptz,status text not null default 'draft' check(status in('draft','ready','scheduled','done')),article_id uuid references public.pageant_articles(id),media_id uuid references public.pageant_media(id),proof_url text not null default '',proof_note text not null default '',version integer not null default 1,created_by uuid references auth.users(id),updated_at timestamptz not null default now(),foreign key(activity_id,project_id)references public.pageant_activities(id,project_id));
create table public.pageant_run_items(
 id uuid primary key default gen_random_uuid(),project_id uuid not null references public.pageant_projects(id),activity_id uuid,title text not null,starts_at timestamptz,ends_at timestamptz,venue text not null default '',position integer not null default 0,responsible text not null default '',cue text not null default '',preparation text not null default '',public boolean not null default false,status text not null default 'draft' check(status in('draft','confirmed','completed','cancelled')),version integer not null default 1,created_by uuid references auth.users(id),updated_at timestamptz not null default now(),foreign key(activity_id,project_id)references public.pageant_activities(id,project_id),check(ends_at is null or starts_at is null or ends_at>starts_at));
do $$declare t text;begin foreach t in array array['pageant_course_plans','pageant_lessons','pageant_lesson_attendance','pageant_homework','pageant_submissions','pageant_guest_invites','pageant_sponsor_packages','pageant_sponsor_leads','pageant_sponsor_deliverables','pageant_campaigns','pageant_run_items']loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from anon,authenticated',t);
 if t not in('pageant_lesson_attendance')then execute format('create trigger %I before update on public.%I for each row execute function public.pageant_increment_version()',t||'_version',t);end if;
end loop;end $$;
create index pageant_lesson_activity on public.pageant_lessons(activity_id,starts_at);
create index pageant_homework_activity on public.pageant_homework(activity_id);
create index pageant_submission_user on public.pageant_submissions(user_id,homework_id);
create index pageant_guest_project on public.pageant_guest_invites(project_id,status);
create index pageant_packages_project on public.pageant_sponsor_packages(project_id,status);
create index pageant_leads_project on public.pageant_sponsor_leads(project_id,status);
create index pageant_leads_member on public.pageant_sponsor_leads(user_id);
create index pageant_delivery_lead on public.pageant_sponsor_deliverables(lead_id,due_at);
create index pageant_campaign_project on public.pageant_campaigns(project_id,due_at);
create index pageant_rundown_project on public.pageant_run_items(project_id,starts_at,position);
create function public.pageant_is_enrolled(p_user uuid,p_activity uuid)returns boolean language sql stable set search_path='' as $$
 select exists(select 1 from public.pageant_registrations where user_id=p_user and activity_id=p_activity and status in('approved','attended')) or exists(select 1 from public.pageant_commerce_orders o join public.pageant_admissions a on a.order_id=o.id where o.user_id=p_user and o.activity_id=p_activity and o.status in('paid','partially_refunded')and a.status in('valid','used'));
$$;
revoke all on function public.pageant_is_enrolled(uuid,uuid)from public,anon,authenticated;
grant execute on function public.pageant_is_enrolled(uuid,uuid)to service_role;
create function public.pageant_ops_respond_invite(p_hash text,p_status text,p_size integer,p_note text)returns jsonb language plpgsql security definer set search_path='' as $$
declare i public.pageant_guest_invites;p public.pageant_projects;begin
 if p_status not in('accepted','declined','contact')or length(p_note)>2000 then raise exception 'invalid_reply';end if;
 select *into i from public.pageant_guest_invites where token_hash=p_hash for update;
 if not found or i.revoked_at is not null or i.expires_at is null or i.expires_at<=now() then raise exception 'invitation_expired';end if;
 select *into p from public.pageant_projects where id=i.project_id;
 if not p.public or p.review_status<>'approved' or p.status in('closed','archived') then raise exception 'invitation_closed';end if;
 if i.activity_id is not null and exists(select 1 from public.pageant_activities where id=i.activity_id and status in('cancelled','archived','closed'))then raise exception 'invitation_closed';end if;
 if i.replied_at is not null then return jsonb_build_object('status',i.status,'party_size',i.party_size,'duplicate',true);end if;
 if p_size<1 or p_size>i.max_party_size then raise exception 'invalid_party_size';end if;
 update public.pageant_guest_invites set status=p_status,party_size=p_size,reply_note=p_note,replied_at=now(),updated_at=now()where id=i.id;
 return jsonb_build_object('status',p_status,'party_size',p_size,'duplicate',false);
end $$;
revoke all on function public.pageant_ops_respond_invite(text,text,integer,text)from public,anon,authenticated;
grant execute on function public.pageant_ops_respond_invite(text,text,integer,text)to service_role;